def fact(n):
    if n == 1:
        return 1
    return n * fact(n - 1)

print(fact(5))

def f(n):
    if n == 0:
        return 0
    return n % 10 + f(n // 10)

print(f(9081))

def g(n):
    if n <= 1:
        return 1
    return g(n - 1) + g(n - 2)

print(g(5))

